\label{lem:tensor}
    Let $M$ be a skew $(A, B)$-bimodule.
    If $J$ is an injective right $A$-module, then $J \otimes_A M$ is a projective right $B$-module.

\label{lem:hom}
    Let $M$ be a skew $(A, B)$-bimodule.
    If $Q$ is a projective right $B$-module, then $\operatorname{Hom}_B(M, Q)$ is an injective right $A$-module.

\label{rmk:skew}
    Let $\mathscr{I}(A)$ and $\mathscr{P}(B)$ denote the categories of injective right $A$-modules and projective right $B$-modules, respectively.
    \index{$I(A)$ @ $\mathscr{I}(A)$ : Category}
    \index{$P(B)$ @ $\mathscr{P}(B)$ : Category}
    If an $(A, B)$-bimodule $M$ induces two functors
    \[
        \begin{tikzcd}[column sep=huge]
            \mathscr{P}(B) \arrow[r, shift left, "{\operatorname{Hom}_B(M, {-})}"] & \mathscr{I}(A) \arrow[l, shift left, "{{-} \otimes_A M}"]
        \end{tikzcd}
    \]
    as in \cref{lem:tensor,lem:hom}, then taking $J = A^*$ and $Q = B$ shows that $M$ is skew.

Let $\Phi_{XY}$ and $\Psi_{XY}$ be the mutually inverse isomorphisms of vector spaces
    \[
        \begin{tikzcd}[column sep=huge]
            \operatorname{Hom}_B(X \otimes_A M, Y) \arrow[r, shift left, "\Phi_{XY}"] & \operatorname{Hom}_A(X, \operatorname{Hom}_B(M, Y)) \arrow[l, shift left, "\Psi_{XY}"]
        \end{tikzcd}
    \]
    that are natural in $X$ and $Y$ from the ordinary tensor-hom adjunction \cite[Theorem II.4.3]{SY11}.
    \index{$\Phi_{XY}$ : Linear Map}
    \index{$\Psi_{XY}$ : Linear Map}
    We begin by proving that these isomorphisms induce
    \[
        \begin{tikzcd}[column sep=huge]
            \mathscr{P}_B(X \otimes_A M, Y) \arrow[r, shift left] & \mathscr{I}_A(X, \operatorname{Hom}_B(M, Y)) \arrow[l, shift left].
        \end{tikzcd}
    \]

    \paragraph{$\Phi_{XY}(\mathscr{P}_B(X \otimes_A M, Y)) \subseteq \mathscr{I}_A(X, \operatorname{Hom}_B(M, Y))$:}
    Assume that $\alpha \colon X \otimes_A M \to Y$ factors through a projective right $B$-module $Q$ as follows.
    \[
        \begin{tikzcd}[
            cells={nodes={text width=4em, align=center}}, row sep=6em
            ]
            X \otimes_A M \arrow[rr, "\alpha"] \arrow[rd, swap, "\beta"] &                              & Y \\
                                                                         & Q \arrow[ru, swap, "\gamma"] &
        \end{tikzcd}
    \]
    Then the following diagram commutes.
    \[
        \begin{tikzcd}[
            cells={nodes={text width=4em, align=center}}, row sep=6em
            ]
            X \arrow[rr, "\Phi_{XY}(\alpha)"] \arrow[rd, swap, "\Phi_{XQ}(\beta)"] &                                                   & \operatorname{Hom}_B(M, Y) \\
                                                                                   & \operatorname{Hom}_B(M, Q) \arrow[ru, swap, "\gamma \circ {-}"] &
        \end{tikzcd}
    \]
    Hence $\Phi_{XY}(\alpha)$ factors through an injective right $A$-module $\operatorname{Hom}_B(M, Q)$ by \cref{lem:hom}.

    \paragraph{$\Psi_{XY}(\mathscr{I}_A(X, \operatorname{Hom}_B(M, Y))) \subseteq \mathscr{P}_B(X \otimes_A M, Y)$:}
    Assume that $\xi \colon X \to \operatorname{Hom}_B(M, Y)$ factors through an injective right $A$-module $J$ as follows.
    \[
        \begin{tikzcd}[
            cells={nodes={text width=4em, align=center}}, row sep=6em
            ]
            X \arrow[rr, "\xi"] \arrow[rd, swap, "\eta"] &                             & \operatorname{Hom}_B(M, Y) \\
                                                         & J \arrow[ru, swap, "\zeta"] &
        \end{tikzcd}
    \]
    \index{$\xi$ : Homomorphism}
    \index{$\eta$ : Homomorphism}
    \index{$\zeta$ : Homomorphism}
    Then the following diagram commutes.
    \[
        \begin{tikzcd}[
            cells={nodes={text width=4em, align=center}}, row sep=6em
            ]
            X \otimes_A M \arrow[rr, "\Psi_{XY}(\xi)"] \arrow[rd, swap, "\eta\otimes1_M"] &                                                    & Y \\
                                                                                          & J \otimes_A M \arrow[ru, swap, "\Psi_{JY}(\zeta)"] &
        \end{tikzcd}
    \]
    \index{$1_M$ : Homomorphism}
    Hence $\Psi_{XY}(\xi)$ factors through a projective right $B$-module $J \otimes_A M$ by \cref{lem:tensor}.

    The above argument shows an isomorphism of quotient spaces.
    Since homomorphisms $X' \to X$ and $Y \to Y'$ induce $X' \otimes_A M \to X \otimes_A M$ and $\operatorname{Hom}_B(M, Y) \to \operatorname{Hom}_B(M, Y')$, it is straightforward to check the naturality.
    \index{$X'$ : Module}
    \index{$Y'$ : Module}

For a simple right $B$-module $V$ and a simple right $A$-module $U$, set
    \[
        n_{VS} = \left[\, {P(V)} \mid {S \otimes_A M} \,\right],
        \qquad
        m_{UT} = \left[\, {I(U)} \mid {\operatorname{Hom}_B(M, T)} \,\right].
    \]
    \index{$V$ : Simple Module}
    \index{$U$ : Simple Module}
    \index{$n_{VS}$ : Natural Number}
    \index{$m_{UT}$ : Natural Number}
    Our theorem reads $n_{TS} = m_{ST}$ with this notation.
    To prove this reciprocity, decompose $S \otimes_A M$ and $\operatorname{Hom}_B(M, T)$ as
    \begin{align*}
        S \otimes_A M &\cong \Omega^0(S \otimes_A M) \oplus \bigoplus_{V \in \operatorname{Irr}(B)} n_{VS} \, P(V), \\
        \operatorname{Hom}_B(M, T)  &\cong \Sigma^0(\operatorname{Hom}_B(M, T)) \oplus \bigoplus_{U \in \operatorname{Irr}(A)} m_{UT} \, I(U).
    \end{align*}
    Recall that the top of $P(V)$ is $V$ and the socle of $I(U)$ is $U$.
    From the top-socle adjunction \cite[Lemma 2.3]{Sa17}, Schur's lemma and the splitting assumption,
    \begin{align*}
        \dim \operatorname{Hom}_B(P(V), T) &= \dim \operatorname{Hom}_B(V, T) = \delta_{VT}, \\
        \dim \operatorname{Hom}_A(S, I(U)) &= \dim \operatorname{Hom}_A(S, U) = \delta_{SU}
    \end{align*}
    with the Kronecker delta.
    \index{$\delta_{VT}$ : Natural Number}
    Thus
    \begin{align}
        \dim \operatorname{Hom}_B(S \otimes_A M, T) &= \dim \operatorname{Hom}_B(\Omega^0(S \otimes_A M), T) + n_{TS}, \label{eq:n_TS} \\
        \dim \operatorname{Hom}_A(S, \operatorname{Hom}_B(M, T))  &= \dim \operatorname{Hom}_A(S, \Sigma^0(\operatorname{Hom}_B(M, T))) + m_{ST}.   \label{eq:m_ST}
    \end{align}
    On the one hand, the ordinary tensor-hom adjunction yields
    \begin{equation}
        \label{eq:whole}
        \dim \operatorname{Hom}_B(S \otimes_A M, T) = \dim \operatorname{Hom}_A(S, \operatorname{Hom}_B(M, T)).
    \end{equation}
    On the other hand, since $M$ is skew,
    \begin{align*}
        \operatorname{Hom}_B(\Omega^0(S \otimes_A M), T)
        &\cong \underline{\operatorname{Hom}}_B(S \otimes_A M, T)            & & \text{by \cref{lem:stable}} \\
        &\cong \overline{\operatorname{Hom}}_A(S, \operatorname{Hom}_B(M, T))             & & \text{by \cref{main:tensor-hom}} \\
        &\cong \operatorname{Hom}_A(S, \Sigma^0(\operatorname{Hom}_B(M, T)))     & & \text{by \cref{lem:costable}.}
    \end{align*}
    This isomorphism of vector spaces yields
    \begin{equation}
        \label{eq:part}
        \dim \operatorname{Hom}_B(\Omega^0(S \otimes_A M), T)
        = \dim \operatorname{Hom}_A(S, \Sigma^0(\operatorname{Hom}_B(M, T))).
    \end{equation}
    Hence
    \begin{align*}
        n_{TS}
        &= \dim \operatorname{Hom}_B(S \otimes_A M, T) - \dim \operatorname{Hom}_B(\Omega^0(S \otimes_A M), T) & & \text{by \eqref{eq:n_TS}} \\
        &= \dim \operatorname{Hom}_A(S, \operatorname{Hom}_B(M, T)) - \dim \operatorname{Hom}_A(S, \Sigma^0(\operatorname{Hom}_B(M, T)))    & & \text{by \eqref{eq:whole}, \eqref{eq:part}} \\
        &= m_{ST}                                                                   & & \text{by \eqref{eq:m_ST}.}
    \end{align*}
    This completes the proof.
